CREATE TABLE IF NOT EXISTS incident_feedback_workflow_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),feedback_id UUID NOT NULL REFERENCES incident_feedback_reports(id) ON DELETE RESTRICT,idempotency_key TEXT NOT NULL,previous_status TEXT NOT NULL CHECK(previous_status IN ('OPEN','IN_PROGRESS','RESOLVED')),new_status TEXT NOT NULL CHECK(new_status IN ('IN_PROGRESS','RESOLVED')),actor TEXT NOT NULL CHECK(NULLIF(BTRIM(actor),'') IS NOT NULL),note TEXT NOT NULL CHECK(NULLIF(BTRIM(note),'') IS NOT NULL),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(feedback_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_feedback_workflow_latest ON incident_feedback_workflow_events(feedback_id,occurred_at DESC);
CREATE TRIGGER incident_feedback_workflow_immutable BEFORE UPDATE OR DELETE ON incident_feedback_workflow_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_decision_record();
